<?php
namespace Tests\Feature;use App\Models\{Campus,HostelRoom};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class MultiCampusIsolationTest extends TestCase{use RefreshDatabase;public function test_campus_scoped_models_never_leak_between_active_campuses():void{$a=Campus::create(['name'=>'Campus A','code'=>'CA']);$b=Campus::create(['name'=>'Campus B','code'=>'CB']);config(['app.active_campus_id'=>$a->id]);HostelRoom::create(['hostel_name'=>'A Hostel','room_number'=>'101','room_type'=>'Standard','bed_capacity'=>2,'cost_per_bed'=>100]);config(['app.active_campus_id'=>$b->id]);HostelRoom::create(['hostel_name'=>'B Hostel','room_number'=>'201','room_type'=>'Standard','bed_capacity'=>2,'cost_per_bed'=>100]);$this->assertSame(['B Hostel'],HostelRoom::pluck('hostel_name')->all());config(['app.active_campus_id'=>$a->id]);$this->assertSame(['A Hostel'],HostelRoom::pluck('hostel_name')->all());$this->assertSame(2,HostelRoom::withoutGlobalScope('campus')->count());}}
